    mp = {}
    res = []
    nxt = 0
    for x in t:
        if x not in mp:
            mp[x] = nxt
            nxt += 1
        res.append(mp[x])
    return tuple(res)


def unite(comp, u, v):
    a, b = comp[u], comp[v]
    if a == b:
        return None
    for i, x in enumerate(comp):
        if x == b:
            comp[i] = a
    return comp


def step_state(st, rim, spoke):
    comp = [st[0], st[1], st[2], 3]  # first vertex, previous vertex, hub, new vertex
    if rim:
        comp = unite(comp, 1, 3)
        if comp is None:
            return None
    if spoke:
        comp = unite(comp, 3, 2)
        if comp is None:
            return None
    return IDX[canon((comp[0], comp[3], comp[2]))]


def build_transitions():
    trans = []
    for has_spoke in (0, 1):
        table = []
        for st in STATES:
            cnt = {}
            for rim in (0, 1):
                for spoke in ((0, 1) if has_spoke else (0,)):
                    to = step_state(st, rim, spoke)
                    if to is not None:
                        cnt[to] = cnt.get(to, 0) + 1
            table.append(list(cnt.items()))
        trans.append(table)
    return trans


def initial_dp(s):
    dp = [0] * 5
    for sp0 in ((0, 1) if s[0] == "1" else (0,)):
        for rim in (0, 1):
            for sp1 in ((0, 1) if s[1] == "1" else (0,)):
                comp = [0, 1, 2]  # vertex 0, vertex 1, hub
                ok = True
                if sp0:
                    comp = unite(comp, 0, 2)
                    ok = comp is not None
                if ok and rim:
                    comp = unite(comp, 0, 1)
                    ok = comp is not None
                if ok and sp1:
                    comp = unite(comp, 1, 2)
                    ok = comp is not None
                if ok:
                    dp[IDX[canon(comp)]] += 1
    return dp


def main():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()

    # Stanley's theorem: distinct orientation indegree sequences = number of forests.
    trans = build_transitions()
    dp = initial_dp(s)

