                                comp[j] = a_
                if ok and sp1:
                    if comp[1] == comp[2]:
                        ok = False
                    else:
                        a_, b_ = comp[1], comp[2]
                        for j in range(3):
                            if comp[j] == b_:
                                comp[j] = a_
                if ok:
                    mp = {}
                    nxt = 0
                    cs = []
                    for x in comp:
                        if x not in mp:
                            mp[x] = nxt
                            nxt += 1
                        cs.append(mp[x])
                    dp[states_idx[tuple(cs)]] += 1

    a, b, c, d, e = dp

    # Main loop with inlined transitions
    for i in range(2, n):
        if s[i] == ONE:
            na = (3*a + b + 2*c) % MOD
            nc = (a + 2*c) % MOD
            nd = (b + 2*d + 2*e) % MOD
            ne = (b + d + 2*e) % MOD
            a = na
            c = nc
            d = nd
            e = ne
            # b unchanged
        else:
            nc = (a + 2*c) % MOD
            ne = (b + d + 2*e) % MOD
            c = nc
            e = ne
            # a, b, d unchanged

    # Close cycle with edge {N-1, 0}:
    # - exclude: contributes sum(dp)
    # - include: only valid when first and prev are in different components
    #   (states 2, 3, 4 where state[0] != state[1])
    ans = (a + b + 2*c + 2*d + 2*e) % MOD
    print(ans)

